[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>CoinTracker Pro — Cryptocurrency Prices, Charts and Market Capitalizations</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
<style>
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --brand-blue: #3861FB;
  --brand-blue-light: #e8ecff;
  --dark-navy: #0D1421;
  --gray-secondary: #808A9D;
  --green: #16c784;
  --red: #ea3943;
  --bg-primary: #ffffff;
  --bg-secondary: #f8f9fa;
  --bg-tertiary: #eff2f5;
  --border-color: #e6e8eb;
  --text-primary: #0D1421;
  --text-secondary: #58667E;
  --text-tertiary: #808A9D;
  --font-mono: 'SF Mono', 'Roboto Mono', 'Fira Code', monospace;
}

body {
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  color: var(--text-primary);
  background: var(--bg-primary);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

a { color: var(--brand-blue); text-decoration: none; }
a:hover { text-decoration: underline; }

/* Top Navigation */
.top-nav {
  background: var(--bg-primary);
  border-bottom: 1px solid var(--border-color);
  position: sticky;
  top: 0;
  z-index: 100;
}

.nav-inner {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 20px;
  display: flex;
  align-items: center;
  height: 56px;
  gap: 28px;
}

.logo {
  font-weight: 700;
  font-size: 18px;
  color: var(--brand-blue);
  white-space: nowrap;
  display: flex;
  align-items: center;
  gap: 8px;
}

.logo svg { flex-shrink: 0; }

.nav-links {
  display: flex;
  gap: 4px;
  list-style: none;
}

.nav-links li a {
  color: var(--text-primary);
  font-size: 14px;
  font-weight: 500;
  padding: 8px 12px;
  border-radius: 8px;
  transition: background 0.15s;
}

.nav-links li a:hover {
  background: var(--bg-tertiary);
  text-decoration: none;
}

.nav-right {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 10px;
}

.btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 16px;
  border-radius: 8px;
  font-size: 14px;
  font-weight: 600;
  border: none;
  cursor: pointer;
  transition: all 0.15s;
  white-space: nowrap;
}

.btn-ghost {
  background: transparent;
  color: var(--text-primary);
}

.btn-ghost:hover { background: var(--bg-tertiary); }

.btn-primary {
  background: var(--brand-blue);
  color: #fff;
}

.btn-primary:hover { background: #2d4fd7; }

.btn-outline {
  background: transparent;
  color: var(--text-secondary);
  border: 1px solid var(--border-color);
}

.btn-outline:hover { background: var(--bg-tertiary); }

.btn-sm { padding: 6px 12px; font-size: 13px; }

/* Container */
.container {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 20px;
}

/* Promotional Banner */
.promo-banner {
  background: linear-gradient(135deg, #1a1a2e, #16213e, #0f3460);
  color: #fff;
  padding: 12px 0;
  overflow: hidden;
  position: relative;
}

.promo-inner {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
}

.promo-text {
  font-size: 14px;
  font-weight: 500;
}

.promo-text span {
  background: linear-gradient(90deg, #ffd700, #ffaa00);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  font-weight: 700;
}

.promo-cta {
  background: rgba(255,255,255,0.15);
  color: #fff;
  padding: 4px 14px;
  border-radius: 20px;
  font-size: 12px;
  font-weight: 600;
  border: 1px solid rgba(255,255,255,0.25);
  cursor: pointer;
  transition: background 0.15s;
}

.promo-cta:hover { background: rgba(255,255,255,0.25); }

.promo-close {
  position: absolute;
  right: 20px;
  top: 50%;
  transform: translateY(-50%);
  background: none;
  border: none;
  color: rgba(255,255,255,0.6);
  cursor: pointer;
  font-size: 18px;
}

/* AI Alerts Bar */
.ai-bar {
  background: var(--bg-secondary);
  border-bottom: 1px solid var(--border-color);
  padding: 12px 0;
}

.ai-bar-inner {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 20px;
}

.ai-topic {
  font-size: 14px;
  font-weight: 600;
  margin-bottom: 8px;
  color: var(--text-primary);
}

.ai-suggestions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.ai-chip {
  background: var(--bg-primary);
  border: 1px solid var(--border-color);
  padding: 5px 12px;
  border-radius: 20px;
  font-size: 12px;
  color: var(--text-secondary);
  cursor: pointer;
  transition: all 0.15s;
  white-space: nowrap;
}

.ai-chip:hover {
  border-color: var(--brand-blue);
  color: var(--brand-blue);
  background: var(--brand-blue-light);
}

/* Market Stats Bar */
.market-stats {
  border-bottom: 1px solid var(--border-color);
  padding: 14px 0;
}

.stats-row {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 20px;
  display: flex;
  gap: 32px;
  flex-wrap: wrap;
  align-items: center;
}

.stat-item {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
}

.stat-label {
  color: var(--text-tertiary);
  font-weight: 500;
}

.stat-value {
  color: var(--text-primary);
  font-weight: 600;
}

.stat-change {
  font-weight: 600;
  font-size: 12px;
}

.stat-change.up { color: var(--green); }
.stat-change.down { color: var(--red); }

.fear-greed-bar {
  width: 60px;
  height: 6px;
  background: linear-gradient(90deg, var(--red), #f5a623, var(--green));
  border-radius: 3px;
  position: relative;
}

.fear-greed-indicator {
  position: absolute;
  top: -3px;
  left: 57%;
  width: 12px;
  height: 12px;
  background: #fff;
  border: 2px solid #f5a623;
  border-radius: 50%;
}

/* Tabs */
.tabs-section {
  padding: 16px 0 0;
}

.tabs-row {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 20px;
}

.tabs {
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
}

.tab {
  padding: 8px 16px;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-secondary);
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.15s;
  border: none;
  background: transparent;
}

.tab:hover {
  background: var(--bg-tertiary);
  color: var(--text-primary);
}

.tab.active {
  background: var(--brand-blue);
  color: #fff;
}

.network-tabs {
  margin-top: 12px;
}

.network-tab {
  padding: 6px 14px;
  font-size: 12px;
  font-weight: 500;
  color: var(--text-tertiary);
  border-radius: 20px;
  cursor: pointer;
  transition: all 0.15s;
  border: 1px solid transparent;
  background: transparent;
}

.network-tab:hover {
  color: var(--text-primary);
  background: var(--bg-tertiary);
}

.network-tab.active {
  border-color: var(--brand-blue);
  color: var(--brand-blue);
  background: var(--brand-blue-light);
}

/* Index Tracker */
.index-tracker {
  max-width: 1400px;
  margin: 12px auto 0;
  padding: 0 20px;
}

.index-row {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 10px 16px;
  background: var(--bg-secondary);
  border-radius: 8px;
  font-size: 13px;
}

.index-name {
  font-weight: 600;
  color: var(--text-primary);
  min-width: 260px;
}

.index-price {
  font-weight: 600;
  font-family: var(--font-mono);
}

/* Table Controls */
.table-controls {
  max-width: 1400px;
  margin: 16px auto 8px;
  padding: 0 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 10px;
}

.table-controls-left {
  display: flex;
  gap: 8px;
  align-items: center;
}

.table-controls-right {
  display: flex;
  gap: 8px;
}

.sort-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 6px 12px;
  font-size: 13px;
  font-weight: 500;
  border-radius: 8px;
  border: 1px solid var(--border-color);
  background: var(--bg-primary);
  color: var(--text-secondary);
  cursor: pointer;
  transition: all 0.15s;
}

.sort-btn.active {
  border-color: var(--brand-blue);
  color: var(--brand-blue);
  background: var(--brand-blue-light);
}

.sort-btn:hover {
  border-color: var(--brand-blue);
}

/* Crypto Table */
.table-wrapper {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 20px;
  overflow-x: auto;
}

.crypto-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

.crypto-table thead th {
  position: sticky;
  top: 56px;
  background: var(--bg-primary);
  padding: 10px 12px;
  text-align: right;
  font-weight: 600;
  color: var(--text-tertiary);
  font-size: 12px;
  border-bottom: 1px solid var(--border-color);
  white-space: nowrap;
  z-index: 10;
}

.crypto-table thead th:nth-child(1),
.crypto-table thead th:nth-child(2) { text-align: left; }

.crypto-table thead th:nth-child(3) { text-align: left; }

.crypto-table tbody tr {
  border-bottom: 1px solid var(--border-color);
  transition: background 0.1s;
}

.crypto-table tbody tr:hover { background: var(--bg-secondary); }

.crypto-table td {
  padding: 12px 12px;
  text-align: right;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.crypto-table td:nth-child(1) {
  text-align: left;
  color: var(--text-tertiary);
  font-weight: 500;
  width: 40px;
}

.crypto-table td:nth-child(2) { text-align: left; }
.crypto-table td:nth-child(3) { text-align: left; }

.coin-info {
  display: flex;
  align-items: center;
  gap: 10px;
}

.coin-icon {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 11px;
  color: #fff;
  flex-shrink: 0;
}

.coin-name-group { display: flex; flex-direction: column; }

.coin-name {
  font-weight: 600;
  color: var(--text-primary);
  font-size: 14px;
}

.coin-symbol {
  font-size: 12px;
  color: var(--text-tertiary);
  font-weight: 500;
}

.price-cell {
  font-weight: 600;
  font-family: var(--font-mono);
  font-size: 13px;
}

.pct-up { color: var(--green); font-weight: 500; }
.pct-down { color: var(--red); font-weight: 500; }

.cap-cell, .vol-cell, .supply-cell {
  font-family: var(--font-mono);
  font-size: 13px;
  color: var(--text-primary);
}

.supply-cell .supply-ticker {
  color: var(--text-tertiary);
  font-size: 11px;
}

.sparkline-cell {
  width: 120px;
  min-width: 120px;
}

.sparkline-cell canvas {
  width: 110px;
  height: 36px;
}

.star-btn {
  background: none;
  border: none;
  cursor: pointer;
  color: var(--text-tertiary);
  font-size: 14px;
  padding: 2px;
  transition: color 0.15s;
}

.star-btn:hover { color: #f5a623; }
.star-btn.active { color: #f5a623; }

/* Pagination */
.pagination {
  max-width: 1400px;
  margin: 0 auto;
  padding: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
}

.page-btn {
  width: 36px;
  height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 500;
  border: 1px solid var(--border-color);
  background: var(--bg-primary);
  color: var(--text-secondary);
  cursor: pointer;
  transition: all 0.15s;
}

.page-btn:hover { border-color: var(--brand-blue); color: var(--brand-blue); }

.page-btn.active {
  background: var(--brand-blue);
  color: #fff;
  border-color: var(--brand-blue);
}

.page-ellipsis {
  width: 36px;
  height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--text-tertiary);
}

.pagination-info {
  margin-left: 16px;
  font-size: 13px;
  color: var(--text-tertiary);
}

/* Market Summary */
.market-summary {
  max-width: 1400px;
  margin: 0 auto;
  padding: 32px 20px 24px;
}

.market-summary h3 {
  font-size: 18px;
  font-weight: 700;
  margin-bottom: 12px;
}

.market-summary p {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.7;
  max-width: 900px;
}

.market-summary strong { color: var(--text-primary); }

.read-more-btn {
  display: inline-block;
  margin-top: 8px;
  font-size: 13px;
  font-weight: 600;
  color: var(--brand-blue);
  cursor: pointer;
  border: none;
  background: none;
}

.read-more-btn:hover { text-decoration: underline; }

.market-extra {
  display: none;
  margin-top: 12px;
}

.market-extra.visible { display: block; }

/* Info Content */
.info-content {
  background: var(--bg-secondary);
  padding: 40px 0;
}

.info-grid {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 20px;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 32px;
}

.info-card h4 {
  font-size: 16px;
  font-weight: 700;
  margin-bottom: 8px;
  color: var(--text-primary);
}

.info-card p {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.7;
}

/* Column Dropdown */
.dropdown-wrapper { position: relative; }

.dropdown-panel {
  display: none;
  position: absolute;
  top: 100%;
  right: 0;
  margin-top: 4px;
  background: var(--bg-primary);
  border: 1px solid var(--border-color);
  border-radius: 12px;
  padding: 12px;
  min-width: 200px;
  box-shadow: 0 8px 24px rgba(0,0,0,0.08);
  z-index: 50;
}

.dropdown-panel.visible { display: block; }

.dropdown-item {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 4px;
  font-size: 13px;
  color: var(--text-primary);
  cursor: pointer;
}

.dropdown-item input[type="checkbox"] {
  accent-color: var(--brand-blue);
  width: 16px;
  height: 16px;
}

/* Filter Panel */
.filter-panel {
  display: none;
  max-width: 1400px;
  margin: 0 auto;
  padding: 16px 20px;
}

.filter-panel.visible { display: block; }

.filter-row {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
  align-items: center;
}

.filter-group label {
  display: block;
  font-size: 12px;
  font-weight: 600;
  color: var(--text-tertiary);
  margin-bottom: 4px;
}

.filter-group select, .filter-group input {
  padding: 6px 12px;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  font-size: 13px;
  background: var(--bg-primary);
  color: var(--text-primary);
}

/* Footer */
.site-footer {
  background: var(--dark-navy);
  color: #fff;
  padding: 48px 0 24px;
  margin-top: 40px;
}

.footer-grid {
  max-width: 1400px;
  margin: 0 auto;
  padding: 0 20px;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
  margin-bottom: 32px;
}

.footer-col h5 {
  font-size: 14px;
  font-weight: 700;
  margin-bottom: 16px;
  color: #fff;
}

.footer-col ul {
  list-style: none;
}

.footer-col li {
  margin-bottom: 8px;
}

.footer-col a {
  color: rgba(255,255,255,0.6);
  font-size: 13px;
  transition: color 0.15s;
}

.footer-col a:hover {
  color: #fff;
  text-decoration: none;
}

.footer-bottom {
  max-width: 1400px;
  margin: 0 auto;
  padding: 24px 20px 0;
  border-top: 1px solid rgba(255,255,255,0.1);
  text-align: center;
  font-size: 13px;
  color: rgba(255,255,255,0.4);
}

/* Responsive */
@media (max-width: 1024px) {
  .nav-links { display: none; }
  .info-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .stats-row { gap: 16px; }
}

@media (max-width: 640px) {
  .footer-grid { grid-template-columns: 1fr; }
  .stats-row { gap: 12px; }
  .stat-item { font-size: 12px; }
  .promo-inner { font-size: 13px; }
}
</style>
</head>
<body>

<!-- Top Navigation -->
<nav class="top-nav">
  <div class="nav-inner">
    <a href="#" class="logo">
      <svg width="28" height="28" viewBox="0 0 28 28" fill="none"><circle cx="14" cy="14" r="14" fill="#3861FB"/><path d="M9 14l3 3 7-7" stroke="#fff" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/></svg>
      CoinTracker Pro
    </a>
    <ul class="nav-links">
      <li><a href="#">Cryptocurrencies</a></li>
      <li><a href="#">Dashboards</a></li>
      <li><a href="#">Exchanges</a></li>
      <li><a href="#">DexScan</a></li>
      <li><a href="#">More</a></li>
    </ul>
