      <button class="btn btn-ghost btn-sm">Log In</button>
      <button class="btn btn-primary btn-sm">Sign Up</button>
    </div>
  </div>
</nav>

<!-- Promotional Banner -->
<div class="promo-banner" id="promoBanner">
