      <button class="ai-chip">What is the market sentiment?</button>
      <button class="ai-chip">What are KOLs discussing?</button>
    </div>
  </div>
</div>

<!-- Market Stats Bar -->
<div class="market-stats">
  <div class="stats-row">
    <div class="stat-item">
      <span class="stat-label">Market Cap:</span>
      <span class="stat-value">$2.56T</span>
      <span class="stat-change up">&#9650; 1.46%</span>
    </div>
    <div class="stat-item">
      <span class="stat-label">CTP20 Index:</span>
      <span class="stat-value">$155.36</span>
      <span class="stat-change up">&#9650; 1.5%</span>
    </div>
    <div class="stat-item">
      <span class="stat-label">Fear &amp; Greed:</span>
