    </div>
    <div class="stat-item">
      <span class="stat-label">Altcoin Season:</span>
      <span class="stat-value">37/100</span>
      <span style="font-size: 12px; color: var(--text-tertiary); font-weight: 500;">Bitcoin season</span>
    </div>
  </div>
</div>

<!-- Category Tabs + Network Filter Tabs -->
<div class="tabs-section">
  <div class="tabs-row">
    <div class="tabs" id="categoryTabs">
      <button class="tab active" data-cat="top">Top</button>
      <button class="tab" data-cat="trending">Trending</button>
      <button class="tab" data-cat="watchlist">Watchlist</button>
      <button class="tab" data-cat="prediction">Prediction Markets</button>
      <button class="tab" data-cat="visited">Most Visited</button>
      <button class="tab" data-cat="new">New</button>
      <button class="tab" data-cat="more">More</button>
    </div>
    <div class="tabs network-tabs" id="networkTabs">
      <button class="network-tab active" data-net="all">All Networks</button>
      <button class="network-tab" data-net="bsc">BSC</button>
      <button class="network-tab" data-net="solana">Solana</button>
      <button class="network-tab" data-net="base">Base</button>
      <button class="network-tab" data-net="ethereum">Ethereum</button>
      <button class="network-tab" data-net="more">More</button>
    </div>
