let activeCategory = "top";
let activeNetwork = "all";

function fmtPrice(p) {
  if (p >= 1000) return "$" + p.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  if (p >= 1) return "$" + p.toFixed(2);
  if (p >= 0.001) return "$" + p.toFixed(4);
  return "$" + p.toFixed(8);
}

function fmtMcap(v) {
  if (v >= 1e12) return "$" + (v / 1e12).toFixed(2) + "T";
  if (v >= 1e9) return "$" + (v / 1e9).toFixed(2) + "B";
  if (v >= 1e6) return "$" + (v / 1e6).toFixed(2) + "M";
  return "$" + v.toLocaleString();
}

function pctClass(v) { return v >= 0 ? "pct-up" : "pct-down"; }
function pctStr(v) { return (v >= 0 ? "+" : "") + v.toFixed(2) + "%"; }

function drawSparkline(canvas, trend, color) {
  const ctx = canvas.getContext("2d");
  const w = canvas.width = 110;
  const h = canvas.height = 36;
  ctx.clearRect(0, 0, w, h);

  let pts = [];
  const n = 20;
  let seed = Math.abs(color.split("").reduce((a, c) => a + c.charCodeAt(0), 0));
  function rng() { seed = (seed * 16807 + 7) % 2147483647; return seed / 2147483647; }

  if (trend === "flat") {
    for (let i = 0; i < n; i++) pts.push(h / 2 + (rng() - 0.5) * 4);
  } else if (trend === "up") {
    for (let i = 0; i < n; i++) pts.push(h * 0.8 - (i / n) * h * 0.55 + (rng() - 0.5) * h * 0.15);
  } else {
    for (let i = 0; i < n; i++) pts.push(h * 0.2 + (i / n) * h * 0.55 + (rng() - 0.5) * h * 0.15);
  }

  const lineColor = trend === "up" ? "#16c784" : trend === "flat" ? "#808A9D" : "#ea3943";

  ctx.beginPath();
  const step = w / (n - 1);
  for (let i = 0; i < n; i++) {
    const x = i * step;
    if (i === 0) ctx.moveTo(x, pts[i]);
    else {
      const px = (i - 1) * step;
      const cx = (px + x) / 2;
      ctx.bezierCurveTo(cx, pts[i - 1], cx, pts[i], x, pts[i]);
    }
  }
  ctx.strokeStyle = lineColor;
  ctx.lineWidth = 1.5;
  ctx.stroke();

  ctx.lineTo(w, h);
  ctx.lineTo(0, h);
  ctx.closePath();
  const grad = ctx.createLinearGradient(0, 0, 0, h);
  grad.addColorStop(0, lineColor + "30");
  grad.addColorStop(1, lineColor + "05");
  ctx.fillStyle = grad;
  ctx.fill();
}

function renderTable() {
  const body = document.getElementById("cryptoBody");
  let coins = [...COINS];

  if (activeNetwork !== "all") {
    coins = coins.filter(c => c.network === activeNetwork);
  }

  if (activeCategory === "trending") {
    coins = [...coins].sort((a, b) => b.h24 - a.h24);
  } else if (activeCategory === "new") {
    coins = [...coins].sort((a, b) => b.rank - a.rank);
  } else if (activeCategory === "visited") {
    coins = coins.slice(0, 50);
  }

  body.innerHTML = coins.map(c => `
    <tr>
      <td>${c.rank}</td>
      <td>
        <div class="coin-info">
          <div class="coin-icon" style="background:${c.color}">${c.symbol.substring(0, 2)}</div>
          <div class="coin-name-group">
            <span class="coin-name">${c.name}</span>
            <span class="coin-symbol">${c.symbol}</span>
          </div>
        </div>
      </td>
      <td class="price-cell col-price">${fmtPrice(c.price)}</td>
      <td class="col-1h"><span class="${pctClass(c.h1)}">${pctStr(c.h1)}</span></td>
      <td class="col-24h"><span class="${pctClass(c.h24)}">${pctStr(c.h24)}</span></td>
      <td class="col-7d"><span class="${pctClass(c.d7)}">${pctStr(c.d7)}</span></td>
      <td class="cap-cell col-mcap">${fmtMcap(c.mcap)}</td>
      <td class="vol-cell col-vol">${fmtMcap(c.vol)}</td>
      <td class="supply-cell col-supply">${c.supply} <span class="supply-ticker">${c.supplyTicker}</span></td>
      <td class="sparkline-cell col-spark"><canvas data-trend="${c.sparkTrend}" data-color="${c.color}"></canvas></td>
    </tr>
  `).join("");

  document.querySelectorAll(".sparkline-cell canvas").forEach(canvas => {
    drawSparkline(canvas, canvas.dataset.trend, canvas.dataset.color);
  });
}

// Category tabs
document.getElementById("categoryTabs").addEventListener("click", e => {
  const tab = e.target.closest(".tab");
  if (!tab) return;
  document.querySelectorAll("#categoryTabs .tab").forEach(t => t.classList.remove("active"));
  tab.classList.add("active");
  activeCategory = tab.dataset.cat;
  renderTable();
});

// Network tabs
document.getElementById("networkTabs").addEventListener("click", e => {
  const tab = e.target.closest(".network-tab");
  if (!tab) return;
  document.querySelectorAll("#networkTabs .network-tab").forEach(t => t.classList.remove("active"));
  tab.classList.add("active");
  activeNetwork = tab.dataset.net;
  renderTable();
});

// Columns dropdown
document.getElementById("columnsBtn").addEventListener("click", e => {
  e.stopPropagation();
  document.getElementById("columnsDropdown").classList.toggle("visible");
});

document.getElementById("columnsDropdown").addEventListener("change", e => {
  const col = e.target.dataset.col;
  const visible = e.target.checked;
  document.querySelectorAll(`.col-${col}`).forEach(el => {
    el.style.display = visible ? "" : "none";
  });
});

// Filters panel
document.getElementById("filtersBtn").addEventListener("click", () => {
  document.getElementById("filterPanel").classList.toggle("visible");
});

// Sort buttons
document.getElementById("sortMcap").addEventListener("click", function() {
  this.classList.add("active");
  document.getElementById("sortVol").classList.remove("active");
  COINS.sort((a, b) => b.mcap - a.mcap);
  renderTable();
});

document.getElementById("sortVol").addEventListener("click", function() {
  this.classList.add("active");
  document.getElementById("sortMcap").classList.remove("active");
  COINS.sort((a, b) => b.vol - a.vol);
  renderTable();
});

// Pagination
document.querySelectorAll(".page-btn").forEach(btn => {
  btn.addEventListener("click", function() {
    document.querySelectorAll(".page-btn").forEach(b => b.classList.remove("active"));
    this.classList.add("active");
  });
});

// Close dropdowns on outside click
document.addEventListener("click", () => {
  document.getElementById("columnsDropdown").classList.remove("visible");
});

// Market Summary toggle
function toggleMarketExtra() {
  const extra = document.getElementById("marketExtra");
  const btn = document.getElementById("readMoreBtn");
  extra.classList.toggle("visible");
  btn.innerHTML = extra.classList.contains("visible") ? "Show Less &#9652;" : "Read More &#9662;";
}

renderTable();
</script>
